import pandas as pd

import config
import database
import models


INVITATIONS_SQL = '''SELECT v.id,v.sender_id,v.recipient_id,v.event_id,v.status,v.is_simulated,
    v.created_at,v.answered_at,sender.display_name AS sender_name,
    recipient.display_name AS recipient_name,e.start_time,e.end_time,s.title,
    d.key AS direction_key,b.name AS bundle_name,e.status AS event_status
    FROM invitations v JOIN users sender ON sender.id=v.sender_id
    JOIN users recipient ON recipient.id=v.recipient_id JOIN events e ON e.id=v.event_id
    JOIN series s ON s.id=e.series_id JOIN bundles b ON b.id=s.bundle_id
    JOIN directions d ON d.id=b.direction_id'''
INVITATION_FILTERS = {'received': ' WHERE v.recipient_id=?', 'sent': ' WHERE v.sender_id=?'}


def _require_user(connection, user_id):
    """Return a known profile row, rejecting malformed IDs before SQLite binding."""
    if type(user_id) is not int or user_id <= 0:
        raise ValueError('A valid user profile is required.')
    # Course: A07 – bind values separately from fixed SQL, including all friend and event IDs.
    row = connection.execute('SELECT * FROM users WHERE id=?', (user_id,)).fetchone()
    if row is None:
        raise ValueError('User profile was not found.')
    return row


def add_friend(connection, user_id, code, now=None):
    """Add a code's owner symmetrically; reject unknown, own and duplicate codes.

    :param connection: open SQLite connection
    :param user_id: profile adding the friend
    :param code: six-character code; surrounding spaces and case are normalized
    :param now: injected Zurich creation time
    :return: the new friend's user ID
    """
    _require_user(connection, user_id)
    if not isinstance(code, str):
        raise ValueError('Enter a friend code.')
    code = code.strip().upper()
    friend = connection.execute('SELECT id FROM users WHERE friend_code=?', (code,)).fetchone()
    if friend is None:
        raise ValueError('Friend code was not found.')
    if friend['id'] == user_id:
        raise ValueError('You cannot add your own friend code.')
    with connection:
        if connection.execute('SELECT id FROM friendships WHERE user_id=? AND friend_id=?',
                              (user_id, friend['id'])).fetchone() is not None:
            raise ValueError('You are already friends.')
        stamp = database.to_db_text(config.local_now(now))
        connection.executemany('''INSERT INTO friendships (user_id,friend_id,created_at)
            VALUES (?,?,?)''', [(user_id, friend['id'], stamp), (friend['id'], user_id, stamp)])
    return friend['id']


def get_sharing_opt_in(connection, user_id):
    """Return whether this profile explicitly shares its WeekWise plans."""
    return bool(_require_user(connection, user_id)['sharing_opt_in'])


def set_sharing_opt_in(connection, user_id, enabled):
    """Persist explicit sharing permission; private calendar entries are never part of sharing."""
    _require_user(connection, user_id)
    if type(enabled) is not bool:
        raise ValueError('Sharing must be on or off.')
    with connection:
        connection.execute('UPDATE users SET sharing_opt_in=? WHERE id=?', (int(enabled), user_id))


def get_friends_df(connection, user_id):
    """Return only the supplied user's friends and their public profile/sharing fields."""
    _require_user(connection, user_id)
    return pd.read_sql('''SELECT u.id,u.display_name,u.friend_code,u.sharing_opt_in,u.is_synthetic
        FROM friendships f JOIN users u ON u.id=f.friend_id
        WHERE f.user_id=? ORDER BY u.display_name,u.id''', connection,
                       index_col=['id'], params=(user_id,))


def get_friend_plans_df(connection, user_id, now=None):
    """Read future confirmed WeekWise plans only for friends who opted into sharing."""
    query = '''SELECT i.id,u.id AS friend_id,u.display_name,e.id AS event_id,s.title,
        e.start_time,e.end_time,d.key AS direction_key,b.name AS bundle_name
        FROM friendships f JOIN users u ON u.id=f.friend_id
        JOIN interactions i ON i.user_id=u.id JOIN events e ON e.id=i.event_id
        JOIN series s ON s.id=e.series_id JOIN bundles b ON b.id=s.bundle_id
        JOIN directions d ON d.id=b.direction_id
        WHERE f.user_id=? AND u.sharing_opt_in=1 AND i.status='confirmed' AND e.start_time>?
        ORDER BY e.start_time,u.display_name,e.id'''
    return pd.read_sql(query, connection, index_col=['id'],
                       params=(user_id, database.to_db_text(config.local_now(now))))


def get_friends_going_df(connection, user_id, event_id):
    """Return names only of opted-in friends with confirmed/attended plans for this occurrence."""
    return pd.read_sql('''SELECT u.id,u.display_name FROM friendships f
        JOIN users u ON u.id=f.friend_id JOIN interactions i ON i.user_id=u.id
        WHERE f.user_id=? AND i.event_id=? AND u.sharing_opt_in=1
        AND i.status IN ('confirmed','attended') ORDER BY u.display_name,u.id''',
                       connection, index_col=['id'], params=(user_id, event_id))


def get_invitations(connection, user_id):
    """Return received/sent DataFrames, pending first, without revealing unrelated invitations."""
    _require_user(connection, user_id)
    frames = {}
    for kind, condition in INVITATION_FILTERS.items():
        query = ''.join([INVITATIONS_SQL, condition,
                         " ORDER BY (v.status='pending') DESC,v.created_at DESC,v.id"])
        frames[kind] = pd.read_sql(query, connection, index_col=['id'], params=(user_id,))
    return frames


def pending_invitation_senders(connection, user_id, now=None):
    """Map future pending event IDs to inviter names for stable pins in suggestions."""
    received = get_invitations(connection, user_id)['received']
    now, senders = config.local_now(now), {}
    for row in received.to_dict('records'):
        if (row['status'] == 'pending' and database.from_db_text(row['start_time']) > now
                and row['event_status'] not in config.HIDDEN_STATUSES):
            senders.setdefault(row['event_id'], []).append(row['sender_name'])
    return {event_id: ', '.join(names) for event_id, names in senders.items()}


def _future_event(connection, event_id, now):
    """Require an existing future occurrence that is still open to confirmation."""
    if type(event_id) is not int or event_id <= 0:
        raise ValueError('A valid event is required.')
    row = database.get_event_row(connection, event_id)
    if row is None:
        raise ValueError('Event was not found.')
    event = models.event_from_row(row)
    if event.start <= now:
        raise ValueError('This event has already started.')
    if event.status in config.HIDDEN_STATUSES:
        raise ValueError('This event is full or closed.')
    return event


def _require_confirmed_sender(connection, user_id, event_id):
    """Require the inviter to hold a current confirmation for the exact occurrence."""
    interaction = database.get_interaction(connection, user_id, event_id)
    if interaction is None or interaction['status'] != 'confirmed':
        raise ValueError('Confirm this event before inviting friends.')


def send_invitations(connection, sender_id, event_id, friend_ids, now=None):
    """Queue a validated batch once and immediately simulate synthetic recipients' responses.

    :param connection: open SQLite connection
    :param sender_id: user with a confirmed future event
    :param event_id: one dated occurrence
    :param friend_ids: nonempty iterable of this user's friends
    :param now: injected Zurich clock
    :return: invitation dictionaries in recipient order; repeated sends reuse existing rows
    """
    now = config.local_now(now)
    _require_user(connection, sender_id)
    _future_event(connection, event_id, now)
    _require_confirmed_sender(connection, sender_id, event_id)
    recipients = _invitation_recipients(connection, sender_id, friend_ids)
    ids = []
    with connection:
        for recipient_id in recipients:
            connection.execute('''INSERT INTO invitations
                (sender_id,recipient_id,event_id,created_at) VALUES (?,?,?,?)
                ON CONFLICT(sender_id,recipient_id,event_id) DO NOTHING''',
                               (sender_id, recipient_id, event_id, database.to_db_text(now)))
            row = connection.execute('''SELECT id FROM invitations
                WHERE sender_id=? AND recipient_id=? AND event_id=?''',
                                     (sender_id, recipient_id, event_id)).fetchone()
            ids.append(row['id'])
    results = []
    for invitation_id in ids:
        invitation = _get_invitation(connection, invitation_id)
        if _require_user(connection, invitation['recipient_id'])['is_synthetic']:
            invitation = simulate_friend_response(connection, invitation_id, now)
        results.append(invitation)
    return results


def _invitation_recipients(connection, sender_id, friend_ids):
    """Validate the whole batch before writing; duplicates in the selection are harmless."""
    if not isinstance(friend_ids, (list, tuple, set)) or not friend_ids:
        raise ValueError('Choose at least one friend.')
    known = set(get_friends_df(connection, sender_id).index)
    recipients, seen = [], set()
    for friend_id in friend_ids:
        if type(friend_id) is not int or friend_id not in known:
            raise ValueError('Invitations can be sent only to your friends.')
        if friend_id not in seen:
            recipients.append(friend_id)
            seen.add(friend_id)
    return recipients


def _get_invitation(connection, invitation_id):
    """Read one stored invitation or raise a clear invalid-reference error."""
    if type(invitation_id) is not int or invitation_id <= 0:
        raise ValueError('A valid invitation is required.')
    row = connection.execute('SELECT * FROM invitations WHERE id=?', (invitation_id,)).fetchone()
    if row is None:
        raise ValueError('Invitation was not found.')
    return dict(row)


def _answer_invitation(connection, invitation, accept, now, simulated):
    """Commit the answer and any confirmation together; identical repeated answers are no-ops."""
    status = 'accepted' if accept else 'declined'
    if invitation['status'] != 'pending':
        if invitation['status'] == status:
            return invitation
        raise ValueError('This invitation has already been answered.')
    if accept:
        _future_event(connection, invitation['event_id'], now)
    with connection:
        if accept:
            previous = database.get_interaction(connection, invitation['recipient_id'],
                                                 invitation['event_id'])
            if previous is None or previous['status'] != 'confirmed':
                database.apply_interaction_in_transaction(
                    connection, invitation['recipient_id'], invitation['event_id'],
                    'confirm', now=now)
        connection.execute('''UPDATE invitations SET status=?,answered_at=?,is_simulated=?
            WHERE id=?''', (status, database.to_db_text(now), int(simulated), invitation['id']))
    return _get_invitation(connection, invitation['id'])


def simulate_friend_response(connection, invitation_id, now=None):
    """Answer a synthetic friend's invitation by focus and strict overlap with other plans."""
    invitation = _get_invitation(connection, invitation_id)
    recipient_id = invitation['recipient_id']
    if not _require_user(connection, recipient_id)['is_synthetic']:
        raise ValueError('Only synthetic friends have simulated responses.')
    if invitation['status'] != 'pending':
        return invitation
    now = config.local_now(now)
    try:
        event = _future_event(connection, invitation['event_id'], now)
    except ValueError:
        return _answer_invitation(connection, invitation, False, now, True)
    profile = database.get_user_profile(connection, recipient_id)
    # Touching endpoints are allowed; the same already-confirmed occurrence is not a clash.
    conflict = connection.execute('''SELECT i.id FROM interactions i
        JOIN events e ON e.id=i.event_id WHERE i.user_id=? AND i.status='confirmed'
        AND i.event_id<>? AND e.start_time<? AND e.end_time>? LIMIT 1''',
                                  (recipient_id, event.event_id, database.to_db_text(event.end),
                                   database.to_db_text(event.start))).fetchone()
    accept = profile.wants_direction(event) and conflict is None
    return _answer_invitation(connection, invitation, accept, now, True)


def respond_to_invitation(connection, invitation_id, accept, now=None):
    """Let only the local recipient answer; acceptance confirms then enables ordinary export."""
    if type(accept) is not bool:
        raise ValueError('Choose Accept or Decline.')
    invitation = _get_invitation(connection, invitation_id)
    if invitation['recipient_id'] != database.get_current_user_id(connection):
        raise ValueError('You can answer only invitations addressed to you.')
    return _answer_invitation(connection, invitation, accept, config.local_now(now), False)


def generate_friend_code(existing_codes, rng):
    """Generate a unique readable code for a new profile, with a bounded retry loop.

    :param existing_codes: collection of codes already stored in the database
    :param rng: random.Random instance supplied by the caller
    :return: unused six-character code
    """
    existing_codes = set(existing_codes)
    # Course: U03 s1 – a fixed attempt limit prevents an unbounded collision loop.
    for attempt in range(config.FRIEND_CODE_MAX_ATTEMPTS):
        code = ''.join(rng.choice(config.FRIEND_CODE_ALPHABET)
                       for index in range(config.FRIEND_CODE_LENGTH))
        if code not in existing_codes:
            return code
    raise ValueError('Could not generate a free friend code. Please try again.')


def friends_going_counts(connection, user_id, event_ids):
    """Count only opted-in friends with a confirmed or attended occurrence.

    :param connection: open SQLite connection
    :param user_id: current profile
    :param event_ids: requested IDs; unrelated occurrences are omitted
    :return: event-ID to positive friend count dictionary
    """
    requested = set(event_ids)
    if not requested:
        return {}
    # Fixed joins enforce sharing opt-in before a count leaves the database.
    rows = connection.execute('''SELECT i.event_id,COUNT(*) AS n FROM friendships f
        JOIN users u ON u.id=f.friend_id JOIN interactions i ON i.user_id=u.id
        WHERE f.user_id=? AND u.sharing_opt_in=1 AND i.status IN ('confirmed','attended')
        GROUP BY i.event_id''', (user_id,)).fetchall()
    counts = {}
    for row in rows:
        if row['event_id'] in requested:
            counts[row['event_id']] = row['n']
    return counts


def connect_demo_friends(connection, user_id, friend_id, created_at):
    """Store both directions of a generated friendship, leaving existing links unchanged."""
    with connection:
        connection.executemany('''INSERT OR IGNORE INTO friendships
            (user_id,friend_id,created_at) VALUES (?,?,?)''',
            [(user_id, friend_id, created_at), (friend_id, user_id, created_at)])


def create_demo_invitation(connection, sender_id, recipient_id, event_id, created_at):
    """Seed a pending showcase invitation; no message is sent outside this demo database."""
    with connection:
        connection.execute('''INSERT OR IGNORE INTO invitations
            (sender_id,recipient_id,event_id,status,is_simulated,created_at)
            VALUES (?,?,?,'pending',1,?)''', (sender_id, recipient_id, event_id, created_at))
